const WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** Check digit for the 8 serial digits of a UPU S10 number (see docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  if (!/^\d{8}$/.test(serial)) throw new Error('S10 serial must be 8 digits');
  const sum = WEIGHTS.reduce((acc, weight, i) => acc + weight * Number(serial[i]), 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

export type S10Problem = 'format' | 'check_digit';

/**
 * Validates an Austrian Post S10 number: 2 letters, 8 digits, 1 check digit, `AT`.
 * Expects the number already upper-cased. Returns null if valid.
 */
export function checkAustrianS10(trackingNumber: string): S10Problem | null {
  const match = /^[A-Z]{2}(\d{8})(\d)AT$/.exec(trackingNumber);
  if (!match) return 'format';
  return s10CheckDigit(match[1]) === Number(match[2]) ? null : 'check_digit';
}
